from layout import *
from pathlib import Path
title='类器官神经信号对语言模型游戏探索的影响'
abstract='在生存游戏中，给语言模型同样多次行动机会，读入类器官的电活动能否让它发现更多地图格？我们在训练和测试时回放电极记录，各组按相同的游戏得分训练。芯片 22021 上，每组训练 16 次、每次测试 48 张地图。与屏蔽信号相比，做完 6 次决策后，刺激前自发活动组平均多发现 1.99 格，当轮停发刺激但仍记录放电的零输出组多发现 2.16 格，分别有 14 次和 15 次训练同向。两组都更常选择导航和采集。低生命开局的较大实验也观察到更多新格，但区间跨零。结果支持短程探索改善，信号时序的额外作用及生存收益仍待验证。'
(O/'abstract.txt').write_text(abstract+'\n',encoding='utf-8-sig')
para(title,'Title')
para('Organoid Neural Recordings and Short-Horizon Exploration by a Language Model in a Survival Game','EnglishTitle')
para('作者　［姓名待填］　　　　　单位　［机构待填］','Byline')
h('摘要',small=True);para(abstract)
h('1　引言')
para('一个角色在地图上走了六次，不一定看到了六处新地方。它可能在已经见过的区域来回走，也可能朝远处的地标导航，沿途揭开一片未知区域。《芽野》把这个区别变成了一个可数的问题。在相同的起点、地图和决策次数下，角色比开局多看见了几格？发现格数同时计入视野揭开的相邻格，每格只计一次。')
para('我们检验一种具体的输入方式。类器官（organoid）是在培养条件下形成的三维细胞组织；本文所说的湿件（wetware）指用来提供电活动的这部分生物材料。微电极阵列（microelectrode array，MEA）是一排能在许多位置同时记录微小电变化的电极。我们把已有记录交给大语言模型（large language model，LLM），训练它在游戏里选择动作。模型能读到什么由实验者控制，得分规则保持一致（图 1）。')
para('本文有三项贡献。第一，用同种子、同地图的比较估计每局多发现的格数，同时给出固定游戏时刻的结果（图 2、表 2）。第二，通过拆分得分和清点实际动作，解释为什么角色可以多拿分、又怎样走向地图的新区域（图 3、图 4）。第三，用另一枚样本以及事先登记的压力开局检验结论能推广多远，并估计下一轮需要怎样的辨别能力（表 2、表 3）。')
h('2　相关工作',True)
h('2.1　培养皿中的神经活动可以怎样参与计算',small=True)
para('DishBrain 实验把培养的神经细胞接入一个类似乒乓球的游戏。Kagan 等人通过电极传入游戏信息，从细胞活动读出控制信号，并观察反馈条件下的表现变化 [1]。在那项工作中，神经网络直接参与控制。本研究让语言模型控制角色，电极记录是它可读取的一种观察。这个差别决定了能从游戏结果推断什么：变好的是模型在特定输入下的行为，类器官在游戏过程中是否学习需要另做实验。')
para('类器官智能（organoid intelligence）研究讨论怎样把三维神经组织、电极和计算机连在一起，并强调样本、测量与输入输出接口需要共同刻画 [2]。本文把样本身份和算法重复分别计数。同一份生物记录可以用来训练几十个模型，这有助于估计训练的随机波动；要了解不同生物样本间的差异，还需实际更换类器官（表 1）。')
h('2.2　游戏探索可以直接测量',small=True)
para('语言模型在游戏中可以通过探索获得新资源。Voyager 在 Minecraft 中利用自动课程、可复用的技能代码和环境反馈来扩大探索范围 [3]。《芽野》提供另一种可操作的测量：固定可选动作、起点和测试地图，直接比较相同决策预算下新增的可见面积。这样可以把“改变了行动方式”同“在另一张恰好更容易的地图上行动”区别开来。')
h('2.3　外部波动可能改变动作选择',small=True)
para('强化学习（reinforcement learning）用行动后的得分调整模型，让带来较好结果的选择更可能再次出现。Fortunato 等人把可学习的噪声加进网络权重，在多个游戏任务中观察到探索改善 [4]。本文的波动来自模型读到的输入，位置和生成方式都不同。该工作为一个可检验的解释提供了动机：若效应主要来自随时间变化的扰动，幅度匹配的合成输入也应带来相似变化。第 7 节给出区分这种解释的实验。')
h('3　方法',True)
para('模型从游戏中学习，同时接收事先录下的神经活动。闭环（closed loop）是指一次动作改变游戏，改变后的局面又影响下一次决定。这个回路在《芽野》中实际运行。电极到模型的支路使用离线回放（offline replay），即按计划读取已保存的片段。某局中角色走向哪里，无法改变当时读到的那段历史放电（图 1）。')
fig(1,'fig1_system.png','游戏、语言模型与电极记录的关系。横向下环中，游戏提供状态和得分，模型把选中的动作送回游戏。上方是独立采集的神经信号支路。主要实验的附加奖励权重为零，因此读到神经活动不会直接加分。本图为方法示意。',['docs/MEA_GAME_LOOP_SIM.md',F+'train.py',Reg+'确认性实验登记.md'])
h('3.1　模型能看见什么',small=True)
para('游戏状态（state1）告诉模型角色周围的地形、能到达的地标、背包以及生命、水分和饱食度。神经观察（state2）把电极听到的动静压成四个数：一秒内放电有多频繁、有多少通道活跃、放电是否挤在少数时段，以及放电分散在多少通道。先用校准时段确定典型范围，再把四个数写入模型看到的文字，并送给估计未来得分的网络。这样，四个数可随记录改变，却不会向角色透露地图答案。')
para('角色由 Qwen3.5-0.8B 控制，这是一个约八亿参数的语言模型。策略网络（actor）负责选动作，价值网络（critic）估计往后能拿多少分。训练使用近端策略优化（proximal policy optimization，PPO）：角色先在游戏中试走，再根据实际得分小幅调整选择概率 [5]。两部分都收到神经观察，屏蔽时两处同时置零。')
h('3.2　得分与三种读法',small=True)
para('R1 是游戏自身的分数，角色活过一个游戏刻就能获得一小笔分数，其他行动后果也计入回报。R2 是实验另外设定的反馈分，权重 β 决定它影响训练多少。六组短程比较与确认性实验都取 β=0。确认性实验比较三种读法：顺序组照原样读；屏蔽组将四个数都设为零；打乱组在同一试次内每两秒切一段，交换段的顺序，保留段内变化。顺序对屏蔽检验整份输入的收益，顺序对打乱检验保留原顺序的额外价值。')
h('4　实验设置',True)
para('五枚芯片在项目中承担不同角色。主要短程比较使用 22021 和 22554；确认性实验完整复验的是 22021 在 11 月 19 日取得的一份记录。另三枚芯片分别提供独立的训练背景或采集质控。表 1 把记录时长、实际可用的通道和游戏局数分列，同一芯片上的两枚类器官各占一行。测试局数均按最终评估口径计，训练和先导评估另计。')
